#include <iostream>

using BookId = unsigned int;
enum class Status { queued, finished };

int main()
{
    const int pages{5};
    const int sessions{2};
    const double average = static_cast<double>(pages) / sessions;
    const BookId id{42};
    const Status status{Status::queued};
    std::cout << "Average: " << average << '\n';
    std::cout << "Book " << id << ": "
              << (status == Status::queued ? "queued" : "finished") << '\n';
}
